 <Dialog open={!!obsidianReport} onOpenChange={open=>{if(!open)setObsidianReport(null);}}><DialogContent className="workspace-file-dialog"><DialogTitle>{t('Obsidian import complete','Obsidian 导入完成')}</DialogTitle><DialogDescription>{t('Imported {notes} notes and {attachments} attachments. Skipped {skipped} configuration or unsupported files.','已导入 {notes} 篇笔记、{attachments} 个附件，跳过 {skipped} 个配置或不支持的文件。',{notes:obsidianReport?.notes||0,attachments:obsidianReport?.attachments||0,skipped:obsidianReport?.skipped||0})}</DialogDescription><p className="workspace-file-import-help">{t('Original Markdown is attached to each note. Note embeds and heading/block links open the whole note.','每篇笔记附有原始 Markdown。笔记嵌入及标题、段落链接打开整篇笔记。')}</p>{!!obsidianReport?.warnings.length&&<div className="obsidian-import-warnings"><p>{t('Review these items:','以下内容需要核对：')}</p><ul>{obsidianReport.warnings.map((warning,index)=><li key={index}><strong>{warning.path}</strong><span>{warning.message}</span></li>)}</ul></div>}<div className="workspace-file-dialog-actions"><button type="button" onClick={()=>setObsidianReport(null)}>{t('Done','完成')}</button></div></DialogContent></Dialog>
